#include <iostream>
#include <vector>
#include <algorithm>
#include <unordered_map>

using namespace std;
typedef long long ll;
const ll MOD = 1000000007;

ll add_mod(ll x, ll y) {
    return (x + y) % MOD;
}

ll sub_mod(ll x, ll y) {
    x -= y;
    return (x < 0) ? x + MOD : x;
}

ll multiply_mod(ll x, ll y) {
    return (x * y) % MOD;
}

ll power_mod(ll base, ll exp) {
    if (exp == 0) return 1;
    if (exp & 1) return multiply_mod(base, power_mod(base, exp - 1));
    return power_mod(multiply_mod(base, base), exp >> 1);
}

ll inverse_mod(ll x) {
    return power_mod(x, MOD - 2);
}

int size_n;
vector<vector<ll>> matrixA;
ll T_table[8][1 << 7][1 << 7];
vector<unordered_map<ll,ll>> DP_states;
vector<int> family_count(1 << 7, 0);
vector<int> family_index(1 << 7, 0);
vector<vector<int>> family_masks;

void precompute() {
    family_masks.resize(size_n + 1);
    for (int mask = 1; mask < (1 << size_n); ++mask) {
        family_count[mask] = family_count[mask >> 1] + (mask & 1);
    }
    for (int mask = 0; mask < (1 << size_n); ++mask) {
        family_index[mask] = (int)family_masks[family_count[mask]].size();
        family_masks[family_count[mask]].push_back(mask);
    }
    for (int k = 0; k <= size_n; ++k) {
        for (int i = 0; i < (int)family_masks[k].size(); ++i) {
            int current_mask = family_masks[k][i];
            for (int mask = 0; mask < (1 << size_n); ++mask) {
                ll answer = 0;
                if ((mask & current_mask) == mask) continue;
                for (int x = 0; x < size_n; ++x) {
                    if (current_mask & (1 << x)) continue;
                    if ((mask & (1 << x)) == 0) continue;
                    int new_mask = current_mask | (1 << x);
                    answer |= (1ll << family_index[new_mask]);
                }
                T_table[k][i][mask] = answer;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin >> size_n;
    matrixA.resize(size_n);
    for (int i = 0; i < size_n; ++i) {
        matrixA[i].resize(size_n);
        for (int j = 0; j < size_n; ++j) {
            cin >> matrixA[i][j];
            matrixA[i][j] = multiply_mod(matrixA[i][j], inverse_mod(100));
        }
    }
    precompute();
    DP_states.resize(size_n + 1);
    DP_states[0][1] = 1;
    for (int k = 0; k < size_n; ++k) {
        for (int edges = 0; edges < (1 << size_n); ++edges) {
            ll prob = 1;
            for (int i = 0; i < size_n; ++i) {
                if (edges & (1 << i))
                    prob = multiply_mod(prob, matrixA[k][i]);
                else
                    prob = multiply_mod(prob, sub_mod(1, matrixA[k][i]));
            }
            for (auto &S : DP_states[k]) {
                ll mask = S.first;
                ll new_mask = 0;
                ll p = multiply_mod(prob, S.second);
                for (int i = 0; i < (int)family_masks[k].size(); ++i) {
                    if (mask & (1 << i))
                        new_mask |= T_table[k][i][edges];
                }
                if (new_mask != 0)
                    DP_states[k + 1][new_mask] = add_mod(DP_states[k + 1][new_mask], p);
            }
        }
    }
    cout << DP_states[size_n][1] << "\n";

    return 0;
}
